        int[][] cases={{0,0,0,0},{1000,1000,1000,1000},{1000,999,999,999},{1000,1001,1001,1000},{1000,1004,1001,1003},{1000,1005,1002,1003},{100000,200000,100000,200000},{99999,400004,100000,325002}};
