        scenario();CokerRecipes.recipes.put(Fluids.BITUMEN,new CokerRecipe(1,new ItemStack(NtmItems.COKE_PETROLEUM.get()),null));input(b,Fluids.BITUMEN,10);b.heat=f.heatEnergy=1000;b.progress=60000;b.slots.set(1,ItemStack.EMPTY);tick(l,b);check(b.progress==40010&&b.tanks[0].getFill()==9&&b.slots.get(1).getCount()==1,"at most one completion with edited oversized progress");
        scenario();b.progress=137;b.heat=f.heatEnergy=1000;b.tanks[0].setFill(0);tick(l,b);check(b.progress==137&&b.heat==1000&&!b.wasOn,"missing input retains progress and process heat");input(b,Fluids.WATER,100);tick(l,b);check(b.progress==137&&b.heat==1000,"missing recipe retains progress");input(b,Fluids.BITUMEN,1);b.slots.set(1,new ItemStack(NtmItems.COKE_PETROLEUM.get(),64));f.heatEnergy=1005;tick(l,b);check(b.progress==137&&b.heat==1002&&!b.wasOn,"blocked still pulls heat first");
        scenario();input(b,Fluids.WATZ,4000);b.slots.set(1,ItemStack.EMPTY);b.heat=f.heatEnergy=1000;tick(l,b);check(b.progress==147,"switch recipe retains accumulated progress");
