        l.isClientSide=true;input(b,Fluids.BITUMEN,16000);b.heat=100000;b.progress=19999;b.wasOn=false;tick(l,b);check(b.tanks[0].getFill()==16000&&b.progress==19999&&b.heat==100000,"client never processes");
